/*
 * The signed-in user's orders and tickets (SRS 4.7). Contract: docs/backend-contract.md, "Orders and tickets".
 * The QR image and the PDF are generated by the server; the QR carries a signed token, so it can't be
 * forged on the client. Card details never appear here.
 */
import { request } from './http';

export type OrderStatus = 'paid' | 'confirmed' | 'partially_refunded' | 'refunded' | 'cancelled';
export type TicketStatus = 'valid' | 'checked_in' | 'cancelled' | 'refunded';

export interface EventSnapshot {
  id: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
  timeZone: string;
  venue: { name: string; address: string; city: string };
}

export interface Ticket {
  /** The one ticket identifier, shared by the digital and printed copies (SRS 4.7). */
  id: string;
  orderId: string;
  orderNumber: string;
  event: EventSnapshot;
  ticketTypeName: string;
  attendeeName: string;
  /** Assigned seating (SRS 4.3.1); null for general admission. */
  seat: { section: string; row: string; seat: string } | null;
  status: TicketStatus;
  checkedInAt?: Date;
  /** Server-generated QR (SVG) with a signed token. Omitted for cancelled and refunded tickets. */
  qrImageUrl: string | null;
  /** Print-optimized PDF, served as a download. */
  pdfUrl: string;
}

export interface OrderListItem {
  id: string;
  number: string;
  status: OrderStatus;
  event: EventSnapshot;
  total: number;
  ticketCount: number;
  paymentsSimulated: boolean;
  createdAt: Date;
}

export interface Order extends OrderListItem {
  lines: { ticketTypeId: string; name: string; quantity: number; unitPrice: number; lineTotal: number }[];
  subtotal: number;
  discount: number;
  promoCode: string | null;
  fee: number;
  /** Only the method label, e.g. "Simulated card"; never card numbers. */
  paymentMethod: string | null;
  tickets: Ticket[];
}

export interface OrdersApi {
  listMyOrders(): Promise<OrderListItem[]>;
  getMyOrder(id: string): Promise<Order>;
  listMyTickets(): Promise<Ticket[]>;
  getMyTicket(id: string): Promise<Ticket>;
}

// ---- Wire format: same shapes with ISO date strings ----

type EventSnapshotDto = Omit<EventSnapshot, 'startsAt' | 'endsAt'> & { startsAt: string; endsAt: string };
export type TicketDto = Omit<Ticket, 'event' | 'checkedInAt'> & { event: EventSnapshotDto; checkedInAt?: string };
export type OrderListItemDto = Omit<OrderListItem, 'event' | 'createdAt'> & { event: EventSnapshotDto; createdAt: string };
export type OrderDto = Omit<Order, 'event' | 'createdAt' | 'tickets'> & {
  event: EventSnapshotDto;
  createdAt: string;
  tickets: TicketDto[];
};

const eventFromDto = (e: EventSnapshotDto): EventSnapshot => ({ ...e, startsAt: new Date(e.startsAt), endsAt: new Date(e.endsAt) });

export const ticketFromDto = (dto: TicketDto): Ticket => ({
  ...dto,
  event: eventFromDto(dto.event),
  checkedInAt: dto.checkedInAt ? new Date(dto.checkedInAt) : undefined,
});

const listItemFromDto = (dto: OrderListItemDto): OrderListItem => ({
  ...dto,
  event: eventFromDto(dto.event),
  createdAt: new Date(dto.createdAt),
});

export const orderFromDto = (dto: OrderDto): Order => ({
  ...dto,
  event: eventFromDto(dto.event),
  createdAt: new Date(dto.createdAt),
  tickets: dto.tickets.map(ticketFromDto),
});

export const httpOrdersApi: OrdersApi = {
  async listMyOrders() {
    return (await request<OrderListItemDto[]>('/api/me/orders')).map(listItemFromDto);
  },
  async getMyOrder(id) {
    return orderFromDto(await request<OrderDto>(`/api/me/orders/${encodeURIComponent(id)}`));
  },
  async listMyTickets() {
    return (await request<TicketDto[]>('/api/me/tickets')).map(ticketFromDto);
  },
  async getMyTicket(id) {
    return ticketFromDto(await request<TicketDto>(`/api/me/tickets/${encodeURIComponent(id)}`));
  },
};
